function templatesPage(){const automatic=templates.automatic_email||[],automaticSection=`<details class="card automatic-template-card"><summary class="card-head"><div><h2>E-mails automatiques du formulaire</h2><small>E-mails envoyés après une demande d’informations formation. Ils sont gérés par le formulaire et affichés ici en lecture seule.</small></div><span class="automatic-template-meta"><span class="automatic-template-count">${automatic.length} formation${automatic.length>1?'s':''}</span><span class="automatic-template-chevron" aria-hidden="true">⌄</span></span></summary><div class="template-list">${automatic.map((t,i)=>`<div class="template-row"><div class="template-summary"><b>${esc(t.nom)}</b><small>${esc(t.sujet)}</small><span class="automatic-template-badge">Envoi automatique · ${esc(t.formation)}</span></div><div class="template-actions"><button class="btn" data-preview-automatic-template="${i}" aria-label="Prévisualiser l’e-mail automatique ${esc(t.nom)}">Prévisualiser</button></div></div>`).join('')||'<div class="empty">Aucun e-mail automatique</div>'}</div></details>`;page.innerHTML=header('BIBLIOTHÈQUE','Modèles de messages','Consultez les e-mails automatiques et créez vos propres modèles e-mail HTML et SMS.')+templateVariablesHtml()+`<div class="template-grid">${['email','sms'].map(type=>`<section class="card"><div class="card-head"><h2>${type==='email'?'Modèles e-mail personnalisés':'Modèles SMS'}</h2><button class="btn blue" data-add-template="${type}">＋ ${type==='email'?'Ajouter un mail':'Ajouter un SMS'}</button></div><div class="template-list">${templates[type].map((t,i)=>`<div class="template-row"><div class="template-summary"><b>${esc(t.nom)}</b><small>${type==='email'?esc(t.sujet):esc(t.contenu).slice(0,80)}</small></div><div class="template-actions"><button class="btn" data-preview-template="${i}" data-preview-type="${type}" aria-label="Prévisualiser le modèle ${esc(t.nom)}">Prévisualiser</button><button class="btn" data-edit-template="${i}" data-edit-type="${type}" aria-label="Modifier le modèle ${esc(t.nom)}">Modifier</button><button class="btn danger" data-delete-template="${i}" data-delete-type="${type}" aria-label="Supprimer le modèle ${esc(t.nom)}">Supprimer</button></div></div>`).join('')||'<div class="empty">Aucun modèle</div>'}</div></section>`).join('')}</div>`+automaticSection;document.querySelectorAll('[data-copy-variable]').forEach(b=>b.onclick=async()=>{await navigator.clipboard.writeText(b.dataset.copyVariable);toast(`Variable ${b.dataset.copyVariable} copiée`)});document.querySelectorAll('[data-add-template]').forEach(b=>b.onclick=()=>b.dataset.addTemplate==='email'?emailTemplateChoiceModal():templateModal('sms'));document.querySelectorAll('[data-edit-template]').forEach(b=>b.onclick=()=>templateModal(b.dataset.editType,templates[b.dataset.editType][Number(b.dataset.editTemplate)]));document.querySelectorAll('[data-delete-template]').forEach(b=>b.onclick=()=>deleteTemplate(b.dataset.deleteType,templates[b.dataset.deleteType][Number(b.dataset.deleteTemplate)]));document.querySelectorAll('[data-preview-automatic-template]').forEach(b=>b.onclick=()=>{const t=automatic[Number(b.dataset.previewAutomaticTemplate)];if(t)previewModal(t.contenu,true)});document.querySelectorAll('[data-preview-template]').forEach(b=>b.onclick=()=>{const type=b.dataset.previewType,t=templates[type][Number(b.dataset.previewTemplate)];if(!t)return;if(type==='sms')previewModal(smsPreviewHtml(t.contenu),false,null,{contenu:t.contenu});else previewModal(t.contenu,true,{sujet:t.sujet,contenu:t.contenu})})}
