const emailContentPattern=/<!-- EMAIL_CONTENT_START -->([\s\S]*?)<!-- EMAIL_CONTENT_END -->/;
const emailHeaderPatterns={title:/<!-- EMAIL_HEADER_TITLE_START -->([\s\S]*?)<!-- EMAIL_HEADER_TITLE_END -->/,subtitle:/<!-- EMAIL_HEADER_SUBTITLE_START -->([\s\S]*?)<!-- EMAIL_HEADER_SUBTITLE_END -->/,tagline:/<!-- EMAIL_HEADER_TAGLINE_START -->([\s\S]*?)<!-- EMAIL_HEADER_TAGLINE_END -->/};
function emailContentToHtml(content){return String(content||'').trim().split(/\n\s*\n/).filter(Boolean).map(paragraph=>`<p>${esc(paragraph).replace(/\n/g,'<br>')}</p>`).join('')}
function emailContentToText(html){const container=document.createElement('div');container.innerHTML=html;container.querySelectorAll('br').forEach(br=>br.replaceWith('\n'));container.querySelectorAll('p').forEach(p=>p.insertAdjacentText('afterend','\n\n'));return container.textContent.trim()}
function replaceEmailMarker(html,pattern,startMarker,endMarker,value){return html.replace(pattern,`${startMarker}${esc(value)}${endMarker}`)}
function templateModal(type,existing=null,starter=''){const mail=type==='email',editing=!!existing,initialBody=existing?.contenu||starter,usesStarter=mail&&emailContentPattern.test(initialBody),contentMatch=usesStarter?initialBody.match(emailContentPattern):null,hasEditableHeader=usesStarter&&Object.values(emailHeaderPatterns).every(pattern=>pattern.test(initialBody));modal(`${editing?'Modifier':'Nouveau'} modèle ${mail?'e-mail':'SMS'}`,`<div class="field"><label>Nom du modèle</label><input id="tplName" placeholder="Ex. Confirmation RDV" value="${esc(existing?.nom||'')}"></div>${mail?`<div class="field"><label>Objet</label><input id="tplSubject" value="${esc(existing?.sujet||'')}"></div>`:''}${usesStarter?`${hasEditableHeader?`<fieldset class="email-header-fields"><legend>Header du mail</legend><small class="field-help">Personnalisez les trois textes du bandeau bleu. Les variables comme {{ formation }} sont acceptées.</small><div class="field"><label for="tplHeaderTitle">Titre</label><input id="tplHeaderTitle" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.title)[1]))}"></div><div class="field"><label for="tplHeaderSubtitle">Sous-titre</label><input id="tplHeaderSubtitle" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.subtitle)[1]))}"></div><div class="field"><label for="tplHeaderTagline">Accroche</label><input id="tplHeaderTagline" value="${esc(emailContentToText(initialBody.match(emailHeaderPatterns.tagline)[1]))}"></div></fieldset>`:''}<div class="field email-content-field"><label for="tplContent">Contenu du mail</label><small class="field-help">Saisissez uniquement votre message : la mise en page du modèle est conservée automatiquement.</small><textarea id="tplContent" rows="8" placeholder="Rédigez ici le contenu de votre e-mail…">${esc(emailContentToText(contentMatch[1]).replace('Écrivez ici le contenu de votre e-mail.',''))}</textarea></div><details class="email-code-details"><summary>Modifier le code HTML (avancé)</summary><div class="field"><textarea id="tplBody" aria-label="Code HTML du modèle">${esc(initialBody)}</textarea></div></details>`:`<div class="field"><label>${mail?'Code HTML':'Texte du SMS'}</label>${mail?'<small class="field-help">Le code complet reste modifiable et peut être récupéré à tout moment via « Prévisualiser », puis « Copier le code HTML ».</small>':''}<textarea id="tplBody" style="min-height:320px" placeholder="${mail?'Collez ici votre code HTML…':'Bonjour…'}">${esc(initialBody)}</textarea></div>`}`,`<button class="btn blue" id="saveTpl">${editing?'Enregistrer les modifications':'Enregistrer le modèle'}</button>`);if(usesStarter){tplContent.oninput=()=>{tplBody.value=tplBody.value.replace(emailContentPattern,`<!-- EMAIL_CONTENT_START -->${emailContentToHtml(tplContent.value)}<!-- EMAIL_CONTENT_END -->`)};if(hasEditableHeader){const syncHeader=()=>{tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.title,'<!-- EMAIL_HEADER_TITLE_START -->','<!-- EMAIL_HEADER_TITLE_END -->',tplHeaderTitle.value);tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.subtitle,'<!-- EMAIL_HEADER_SUBTITLE_START -->','<!-- EMAIL_HEADER_SUBTITLE_END -->',tplHeaderSubtitle.value);tplBody.value=replaceEmailMarker(tplBody.value,emailHeaderPatterns.tagline,'<!-- EMAIL_HEADER_TAGLINE_START -->','<!-- EMAIL_HEADER_TAGLINE_END -->',tplHeaderTagline.value)};[tplHeaderTitle,tplHeaderSubtitle,tplHeaderTagline].forEach(input=>input.oninput=syncHeader)}document.querySelector('.email-code-details').ontoggle=e=>{if(e.currentTarget.open){const match=tplBody.value.match(emailContentPattern);if(match)tplContent.value=emailContentToText(match[1])}}}saveTpl.onclick=async()=>{if(!tplName.value.trim()||!tplBody.value.trim()||(usesStarter&&!tplContent.value.trim()))return toast('Le nom et le contenu sont obligatoires',true);saveTpl.disabled=true;try{const t=await api(editing?`/api/crm/templates/${existing.id}`:'/api/crm/templates',{method:editing?'PATCH':'POST',body:JSON.stringify({type,nom:tplName.value,sujet:mail?tplSubject.value:'',contenu:tplBody.value})});if(editing)templates[type][templates[type].findIndex(x=>x.id===existing.id)]=t;else templates[type].push(t);closeModal();templatesPage();toast(editing?'Modèle modifié':'Modèle enregistré')}catch(e){toast(e.message,true);saveTpl.disabled=false}}}
async function deleteTemplate(type,t){if(!t||!window.confirm(`Supprimer définitivement le modèle « ${t.nom} » ?`))return;try{await api(`/api/crm/templates/${t.id}`,{method:'DELETE'});templates[type]=templates[type].filter(x=>x.id!==t.id);templatesPage();toast('Modèle supprimé')}catch(e){toast(e.message,true)}}
async function createContact(){modal('Créer une nouvelle piste',`<div class="fields"><div class="field"><label>Prénom</label><input id="newFirst"></div><div class="field"><label>Nom</label><input id="newLast"></div><div class="field full"><label>Formation</label><select id="newTraining">${['APS','A3P','DESP','SSIAP 1','Chauffeur VTC'].map(x=>`<option>${x}</option>`)}</select></div></div>`,`<button class="btn blue" id="createBtn">Créer la piste</button>`);createBtn.onclick=async()=>{if(!newFirst.value&&!newLast.value)return toast('Renseignez au moins un nom',true);try{const c=await api('/api/crm/contacts',{method:'POST',body:JSON.stringify({prenom:newFirst.value,nom:newLast.value,formation:newTraining.value})});contacts.unshift(c);closeModal();showContact(c.id);toast('Nouvelle piste créée')}catch(e){toast(e.message,true)}}}
function deleteCrmDatabaseModal(){adminToolsMenuElement?.classList.remove('open');adminToolsButton?.setAttribute('aria-expanded','false');modal('Supprimer la base de données',`<div class="database-delete-warning"><b>Cette action est irréversible.</b><p>Tous les prospects, toutes les pistes et leur historique CRM seront définitivement supprimés. Les autres données du site ne seront pas affectées.</p><label for="deleteCrmConfirmation">Saisissez <strong>SUPPRIMER</strong> pour confirmer</label><input id="deleteCrmConfirmation" autocomplete="off" placeholder="SUPPRIMER"></div>`,`<button class="btn" id="cancelDatabaseDelete">Annuler</button><button class="btn danger" id="confirmDatabaseDelete" disabled>Supprimer définitivement</button>`,'database-delete-modal');const confirmation=document.querySelector('#deleteCrmConfirmation'),submit=document.querySelector('#confirmDatabaseDelete');document.querySelector('#cancelDatabaseDelete').onclick=closeModal;confirmation.oninput=()=>{submit.disabled=confirmation.value.trim()!=='SUPPRIMER'};submit.onclick=async()=>{submit.disabled=true;submit.textContent='Suppression…';try{const result=await api('/api/crm/database',{method:'DELETE'});contacts=[];crmAppointments=[];notifications=[];localStorage.removeItem('crm-recent-searches');closeModal();C.section='accueil';history.pushState({},'',`/CRM`);render();updateNotificationCount();toast(`${result.deleted_count} fiche${result.deleted_count>1?'s':''} supprimée${result.deleted_count>1?'s':''}`)}catch(e){submit.disabled=false;submit.textContent='Supprimer définitivement';toast(e.message,true)}};confirmation.focus()}
let integrationTimer;function scheduleContactIntegrations(c){clearTimeout(integrationTimer);integrationTimer=setTimeout(async()=>{loadCalendlyAppointments(c,true);try{const data=await api(`/api/crm/contacts/${c.id}/wedof/refresh`,{method:'POST',body:'{}'});updateFundingBadges(c,data.resources||[]);loadWedofTabCount(c,contactWedofTab)}catch(_){refreshFundingBadges(c)}},300)}
function render(){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===C.section));updateLeadCount();if(C.section==='accueil')page.innerHTML=dashboard();else if(C.section==='calendrier')return calendarPage();else if(C.section==='relances')return remindersPage();else if(C.section==='modeles')return templatesPage();else if(C.section==='notifications')return notificationsPage();else{page.innerHTML=listPage(C.section);bindList(C.section)}bindRows()}
async function init(){try{[contacts,templates,formationSessions,notifications,crmAppointments]=await Promise.all([api('/api/crm/contacts'),api('/api/crm/templates'),api('/api/formation-sessions'),api('/api/crm/notifications'),api('/api/crm/calendly/appointments').then(x=>x.appointments||[])]);updateNotificationCount();const fiche=new URLSearchParams(location.search).get('fiche');fiche?showContact(fiche):render()}catch(e){page.innerHTML=`<div class="empty">Impossible de charger le CRM.<br>${esc(e.message)}</div>`}}
const newContactButton=document.querySelector('#newContact'),menuToggleButton=document.querySelector('#menuToggle'),sidebarCollapseButton=document.querySelector('#sidebarCollapse'),adminToolsButton=document.querySelector('#adminToolsBtn'),adminToolsMenuElement=document.querySelector('#adminToolsMenu');
async function loadBrevoSmsCredits(){const balance=document.querySelector('#brevoSmsCredits');if(!balance)return;balance.classList.remove('error');balance.removeAttribute('title');balance.textContent='Actualisation…';try{const result=await api('/api/crm/brevo/sms-credits'),smsRemaining=brevoCreditsToSms(result?.credits);if(smsRemaining===null)throw Error('Le solde SMS Brevo est invalide.');const formattedCredits=formatBrevoCredits(result.credits);balance.textContent=`${new Intl.NumberFormat('fr-FR').format(smsRemaining)} SMS restant${smsRemaining>1?'s':''}`;balance.title=`Solde Brevo : ${formattedCredits} crédit${Number(result.credits)>1?'s':''}`}catch(e){balance.textContent=e.message;balance.classList.add('error')}}
newContactButton.addEventListener('click',createContact);document.querySelector('#manageStatusesTop')?.addEventListener('click',statusesModal);document.querySelector('#deleteCrmDatabase')?.addEventListener('click',deleteCrmDatabaseModal);menuToggleButton.addEventListener('click',()=>document.querySelector('.sidebar').classList.toggle('open'));sidebarCollapseButton?.addEventListener('click',()=>document.body.classList.toggle('sidebar-collapsed'));adminToolsButton?.addEventListener('click',e=>{e.stopPropagation();const opening=!adminToolsMenuElement.classList.contains('open');adminToolsMenuElement.classList.toggle('open',opening);adminToolsButton.setAttribute('aria-expanded',opening);if(opening)loadBrevoSmsCredits()});const searchBox=document.querySelector('.search');searchBox.insertAdjacentHTML('beforeend','<div class="global-results" id="globalResults"></div>');
const searchable=c=>Object.values(c).filter(value=>typeof value!=='object').join(' ').toLowerCase();
const searchPages=[['Accueil','accueil','/CRM'],['Calendrier','calendrier','/CRM/calendrier'],['Notifications','notifications','/CRM/notifications'],['Fil actu','fil-actu','/CRM/fil-actu'],['Pistes','pistes','/CRM/pistes'],['Relances','relances','/CRM/relances'],['Inscrits','inscrits','/CRM/inscrits'],['Disqualifiés','disqualifies','/CRM/disqualifies'],['Contacts','contacts','/CRM/contacts'],['Modèles','modeles','/CRM/modeles']];const recentSearches=()=>JSON.parse(localStorage.getItem('crm-recent-searches')||'[]');const saveRecent=c=>{const next=[c.id,...recentSearches().filter(id=>id!==c.id)].slice(0,5);localStorage.setItem('crm-recent-searches',JSON.stringify(next))};function renderGlobalSearch(){const q=globalSearch.value.trim().toLowerCase(),recent=recentSearches().map(id=>contacts.find(c=>c.id===id)).filter(Boolean).slice(0,5),found=q?contacts.filter(c=>searchable(c).includes(q)).slice(0,5):recent,pageFound=q?searchPages.filter(([label])=>label.toLowerCase().includes(q)).slice(0,5):[];globalResults.innerHTML=(found.length&&!q?'<p>5 dernières pistes consultées</p>':'')+found.map(c=>`<button data-global-id="${c.id}"><span class="avatar">${initials(c)}</span><span><b>${esc(displayName(c))}</b><small>${esc(c.formation||'Dossier')} · ${esc(c.statut)} · ${esc(c.mail||c.telephone||'')}</small></span></button>`).join('')+pageFound.map(([label,section,url])=>`<button data-global-page="${section}" data-global-url="${url}"><span class="avatar page-avatar">⌁</span><span><b>${esc(label)}</b><small>Ouvrir la rubrique CRM</small></span></button>`).join('')||(q?'<p>Aucun résultat trouvé</p>':'');globalResults.classList.toggle('open',!!q||!!found.length);document.querySelectorAll('[data-global-id]').forEach(b=>b.onclick=()=>{const c=contacts.find(x=>x.id===b.dataset.globalId);if(c)saveRecent(c);globalSearch.value='';globalResults.classList.remove('open');showContact(b.dataset.globalId)});document.querySelectorAll('[data-global-page]').forEach(b=>b.onclick=()=>{C.section=b.dataset.globalPage;globalSearch.value='';globalResults.classList.remove('open');history.pushState({},'',b.dataset.globalUrl);render()})}globalSearch.onfocus=renderGlobalSearch;globalSearch.oninput=renderGlobalSearch;
document.addEventListener('click',e=>{if(!searchBox.contains(e.target))globalResults.classList.remove('open')});
globalSearch.onkeydown=e=>{if(e.key==='Enter'){C.section='contacts';history.pushState({},'',`/CRM/contacts`);render();const x=document.querySelector('#listSearch');if(x){x.value=globalSearch.value;x.dispatchEvent(new Event('input'))}}};window.onpopstate=()=>location.reload();init();
// Synchronisation légère : les compteurs et fils collaboratifs évoluent sans recharger la page.
setInterval(async()=>{try{const fresh=await api('/api/crm/contacts');contacts=fresh;updateLeadCount();const id=new URLSearchParams(location.search).get('fiche'),current=contacts.find(c=>c.id===id);if(current){const feedRoot=document.querySelector('#activityFeed'),pubRoot=document.querySelector('#publicationFeed');if(feedRoot)feedRoot.innerHTML=feed(current);if(pubRoot){pubRoot.innerHTML=publications(current);bindPublicationFeed(current,pubRoot)}}}catch(_){/* Une coupure réseau ne doit pas interrompre la saisie. */}},15000);
